import{_ as t,a0 as o,w as r,s as d,ao as l,I as e,x as a,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何管理你的 Linux 环境变量 | LCTT x X-CMD","titleTemplate":false,"description":"如何管理你的 Linux 环境变量 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何管理你的 Linux 环境变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何管理你的 Linux 环境变量 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190329 How to manage your Linux environment","title":"如何管理你的 Linux 环境变量","tag":"201905","desc":""},"relativePath":"201905/20190329 How to manage your Linux environment.md","filePath":"[post].md"}'),h={name:"201905/20190329 How to manage your Linux environment.md"};function g(c,s,u,b,k,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=l(`<h1 id="如何管理你的-linux-环境变量" tabindex="-1">如何管理你的 Linux 环境变量 <a class="header-anchor" href="#如何管理你的-linux-环境变量" aria-label="Permalink to “如何管理你的 Linux 环境变量”">​</a></h1><blockquote><p>Linux 用户环境变量可以帮助你找到你需要的命令，无须了解系统如何配置的细节而完成大量工作。而这些设置来自哪里和如何被修改它们是另一个话题。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/environment-rocks-leaves-100792229-large.jpg" alt="IIP Photo Archive CC BY 2.0"></p><p>在 Linux 系统上的用户账户配置以多种方法简化了系统的使用。你可以运行命令，而不需要知道它们的位置。你可以重新使用先前运行的命令，而不用发愁系统是如何追踪到它们的。你可以查看你的电子邮件，查看手册页，并容易地回到你的家目录，而不用管你在文件系统中身在何方。并且，当需要的时候，你可以调整你的账户设置，以便其更符合你喜欢的方式。</p><p>Linux 环境设置来自一系列的文件：一些是系统范围（意味着它们影响所有用户账户），一些是处于你的家目录中的配置文件里。系统范围的设置在你登录时生效，而本地设置在其后生效，所以，你在你账户中作出的更改将覆盖系统范围设置。对于 bash 用户，这些文件包含这些系统文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/environment</span></span>
<span class="line"><span>/etc/bash.bashrc</span></span>
<span class="line"><span>/etc/profile</span></span></code></pre></div><p>以及一些本地文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.bashrc</span></span>
<span class="line"><span>~/.profile # 如果有 ~/.bash_profile 或 ~/.bash_login 就不会读此文件</span></span>
<span class="line"><span>~/.bash_profile</span></span>
<span class="line"><span>~/.bash_login</span></span></code></pre></div><p>你可以修改本地存在的四个文件的任何一个，因为它们处于你的家目录，并且它们是属于你的。</p><h3 id="查看你的-linux-环境设置" tabindex="-1">查看你的 Linux 环境设置 <a class="header-anchor" href="#查看你的-linux-环境设置" aria-label="Permalink to “查看你的 Linux 环境设置”">​</a></h3><p>为查看你的环境设置，使用 <code>env</code> 命令。你的输出将可能与这相似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env</span></span>
<span class="line"><span>LS_COLORS=rs=0:di=01;34:ln=01;36:mh=00:pi=40;33:so=01;35:do=01;35:bd=40;33;01:cd=40;33;</span></span>
<span class="line"><span>01:or=40;31;01:mi=00:su=37;41:sg=30;43:ca=30;41:tw=30;42:ow=34;42:st=37;44:ex=01;32:</span></span>
<span class="line"><span>*.tar=01;31:*.tgz=01;31:*.arc=01;31:*.arj=01;31:*.taz=01;31:*.lha=01;31:*.lz4=01;31:</span></span>
<span class="line"><span>*.lzh=01;31:*.lzma=01;31:*.tlz=01;31:*.txz=01;31:*.tzo=01;31:*.t7z=01;31:*.zip=01;31:</span></span>
<span class="line"><span>*.z=01;31:*.Z=01;31:*.dz=01;31:*.gz=01;31:*.lrz=01;31:*.lz=01;31:*.lzo=01;31:*.xz=01;</span></span>
<span class="line"><span>31:*.zst=01;31:*.tzst=01;31:*.bz2=01;31:*.bz=01;31:*.tbz=01;31:*.tbz2=01;31:*.tz=01;31:</span></span>
<span class="line"><span>*.deb=01;31:*.rpm=01;31:*.jar=01;31:*.war=01;31:*.ear=01;31:*.sar=01;31:*.rar=01;31:</span></span>
<span class="line"><span>*.alz=01;31:*.ace=01;31:*.zoo=01;31:*.cpio=01;31:*.7z=01;31:*.rz=01;31:*.cab=01;31:</span></span>
<span class="line"><span>*.wim=01;31:*.swm=01;31:*.dwm=01;31:*.esd=01;31:*.jpg=01;35:*.jpeg=01;35:*.mjpg=01;35:</span></span>
<span class="line"><span>*.mjpeg=01;35:*.gif=01;35:*.bmp=01;35:*.pbm=01;35:*.pgm=01;35:*.ppm=01;35:*.tga=01;35:</span></span>
<span class="line"><span>*.xbm=01;35:*.xpm=01;35:*.tif=01;35:*.tiff=01;35:*.png=01;35:*.svg=01;35:*.svgz=01;35:</span></span>
<span class="line"><span>*.mng=01;35:*.pcx=01;35:*.mov=01;35:*.mpg=01;35:*.mpeg=01;35:*.m2v=01;35:*.mkv=01;35:</span></span>
<span class="line"><span>*.webm=01;35:*.ogm=01;35:*.mp4=01;35:*.m4v=01;35:*.mp4v=01;35:*.vob=01;35:*.qt=01;35:</span></span>
<span class="line"><span>*.nuv=01;35:*.wmv=01;35:*.asf=01;35:*.rm=01;35:*.rmvb=01;35:*.flc=01;35:*.avi=01;35:</span></span>
<span class="line"><span>*.fli=01;35:*.flv=01;35:*.gl=01;35:*.dl=01;35:*.xcf=01;35:*.xwd=01;35:*.yuv=01;35:</span></span>
<span class="line"><span>*.cgm=01;35:*.emf=01;35:*.ogv=01;35:*.ogx=01;35:*.aac=00;36:*.au=00;36:*.flac=00;36:</span></span>
<span class="line"><span>*.m4a=00;36:*.mid=00;36:*.midi=00;36:*.mka=00;36:*.mp3=00;36:*.mpc=00;36:*.ogg=00;36:</span></span>
<span class="line"><span>*.ra=00;36:*.wav=00;36:*.oga=00;36:*.opus=00;36:*.spx=00;36:*.spf=00;36:</span></span>
<span class="line"><span>SSH_CONNECTION=192.168.0.21 34975 192.168.0.11 22</span></span>
<span class="line"><span>LESSCLOSE=/usr/bin/lesspipe %s %s</span></span>
<span class="line"><span>LANG=en_US.UTF-8</span></span>
<span class="line"><span>OLDPWD=/home/shs</span></span>
<span class="line"><span>XDG_SESSION_ID=2253</span></span>
<span class="line"><span>USER=shs</span></span>
<span class="line"><span>PWD=/home/shs</span></span>
<span class="line"><span>HOME=/home/shs</span></span>
<span class="line"><span>SSH_CLIENT=192.168.0.21 34975 22</span></span>
<span class="line"><span>XDG_DATA_DIRS=/usr/local/share:/usr/share:/var/lib/snapd/desktop</span></span>
<span class="line"><span>SSH_TTY=/dev/pts/0</span></span>
<span class="line"><span>MAIL=/var/mail/shs</span></span>
<span class="line"><span>TERM=xterm</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>SHLVL=1</span></span>
<span class="line"><span>LOGNAME=shs</span></span>
<span class="line"><span>DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus</span></span>
<span class="line"><span>XDG_RUNTIME_DIR=/run/user/1000</span></span>
<span class="line"><span>PATH=/home/shs/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games:/snap/bin</span></span>
<span class="line"><span>LESSOPEN=| /usr/bin/lesspipe %s</span></span>
<span class="line"><span>_=/usr/bin/env</span></span></code></pre></div>`,12)),e("p",null,[s[1]||(s[1]=a("虽然你可能会看到大量的输出，上面显示的第一大部分用于在命令行上使用颜色标识各种文件类型。当你看到类似 ",-1)),s[2]||(s[2]=e("code",null,"*.tar=01;31:",-1)),s[3]||(s[3]=a(" 这样的东西，这告诉你 ",-1)),s[4]||(s[4]=e("code",null,"tar",-1)),s[5]||(s[5]=a(" 文件将以红色显示在文件列表中，然而 ",-1)),s[6]||(s[6]=e("code",null,"*.jpg=01;35:",-1)),s[7]||(s[7]=a(" 告诉你 jpg 文件将以紫色显现出来。这些颜色旨在使它易于从一个文件列表中分辨出某些文件。你可以在《",-1)),i(n,{href:"https://www.networkworld.com/article/3269587/customizing-your-text-colors-on-the-linux-command-line.html"},{default:p(()=>[...s[0]||(s[0]=[a("在 Linux 命令行中自定义你的颜色",-1)])]),_:1}),s[8]||(s[8]=a("》处学习更多关于这些颜色的定义，和如何自定义它们。",-1))]),s[25]||(s[25]=l(`<p>当你更喜欢一种不加装饰的显示时，一种关闭颜色显示的简单方法是使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l --color=never</span></span></code></pre></div><p>这个命令可以简单地转换到一个别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias ll2=&#39;ls -l --color=never&#39;</span></span></code></pre></div><p>你也可以使用 <code>echo</code> 命令来单独地显现某个设置。在这个命令中，我们显示在历史缓存区中将被记忆命令的数量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span></code></pre></div><p>如果你已经移动到某个位置，你在文件系统中的最后位置会被记在这里：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PWD=/home/shs</span></span>
<span class="line"><span>OLDPWD=/tmp</span></span></code></pre></div><h3 id="作出更改" tabindex="-1">作出更改 <a class="header-anchor" href="#作出更改" aria-label="Permalink to “作出更改”">​</a></h3><p>你可以使用一个像这样的命令更改环境设置，但是，如果你希望保持这个设置，在你的 <code>~/.bashrc</code> 文件中添加一行代码，例如 <code>HISTSIZE=1234</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTSIZE=1234</span></span></code></pre></div><h3 id="export-一个变量的本意是什么" tabindex="-1">“export” 一个变量的本意是什么 <a class="header-anchor" href="#export-一个变量的本意是什么" aria-label="Permalink to ““export” 一个变量的本意是什么”">​</a></h3><p>导出一个环境变量可使设置用于你的 shell 和可能的子 shell。默认情况下，用户定义的变量是本地的，并不被导出到新的进程，例如，子 shell 和脚本。<code>export</code> 命令使得环境变量可用在子进程中发挥功用。</p><h3 id="添加和移除变量" tabindex="-1">添加和移除变量 <a class="header-anchor" href="#添加和移除变量" aria-label="Permalink to “添加和移除变量”">​</a></h3><p>你可以很容易地在命令行和子 shell 上创建新的变量，并使它们可用。然而，当你登出并再次回来时这些变量将消失，除非你也将它们添加到 <code>~/.bashrc</code> 或一个类似的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export MSG=&quot;Hello, World!&quot;</span></span></code></pre></div><p>如果你需要，你可以使用 <code>unset</code> 命令来消除一个变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unset MSG</span></span></code></pre></div><p>如果变量是局部定义的，你可以通过加载你的启动文件来简单地将其设置回来。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span>Hello, World!</span></span>
<span class="line"><span>$ unset $MSG</span></span>
<span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ . ~/.bashrc</span></span>
<span class="line"><span>$ echo $MSG</span></span>
<span class="line"><span>Hello, World!</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>用户账户是用一组恰当的启动文件设立的，创建了一个有用的用户环境，而个人用户和系统管理员都可以通过编辑他们的个人设置文件（对于用户）或很多来自设置起源的文件（对于系统管理员）来更改默认设置。</p><hr>`,23)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),i(n,{href:"https://www.networkworld.com/article/3385516/how-to-manage-your-linux-environment.html"},{default:p(()=>[...s[9]||(s[9]=[a("https://www.networkworld.com/article/3385516/how-to-manage-your-linux-environment.html",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),i(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[11]||(s[11]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),i(n,{href:"https://github.com/robsean"},{default:p(()=>[...s[13]||(s[13]=[a("robsean",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const S=t(h,[["render",g]]);export{v as __pageData,S as default};
